import {STATIC_EDITION} from './deployment.js';
import {publicOfficeUrl} from './office-links.js';
import {escapeHtml as esc,safeUrl} from './core.js';
import {filterPrayers,PrayerPlayer,selectVoice} from './oratory-core.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let data,prayer,player,tab='prayers',reading='both',voices=[],requestGeneration=0;let favorites=[];
try{favorites=JSON.parse(localStorage.getItem('ci-oratory-favorites')||'[]');if(!Array.isArray(favorites))favorites=[];}catch{}
const hours={Matutinum:['Matinas','Vigília e leituras'],Laudes:['Laudes','Louvor da manhã'],Prima:['Prima','Início do trabalho'],Tertia:['Terça','Terceira hora'],Sexta:['Sexta','Meio do dia'],Nona:['Noa','Nona hora'],Vesperae:['Vésperas','Louvor da tarde'],Completorium:['Completas','Oração da noite']};
function status(message){$('#oratory-status').textContent=message;}
function renderList(){const items=filterPrayers(data.entries,$('#prayer-search').value,$('#prayer-category').value,$('#prayer-favorites').checked?favorites:null,$('#prayer-intention').value);$('#prayer-results').textContent=items.length+' textos';$('#prayer-list').innerHTML=items.map(p=>`<button class="prayer-item ${prayer?.id===p.id?'selected':''}" data-prayer="${esc(p.id)}"><small>${esc(p.category)} ${favorites.includes(p.id)?'· ★':''}</small><strong>${esc(p.title)}</strong><span>${esc(p.latinTitle)}</span></button>`).join('')||'<p class="fine-print">Nenhum texto encontrado.</p>';}
function setPrayer(p){player?.stop();prayer=p;$('#prayer-reader').hidden=false;$('#prayer-empty').hidden=true;$('#prayer-title').textContent=p.title;$('#prayer-intentions').innerHTML=(p.intentions||[]).map(t=>'<span>'+esc(t)+'</span>').join('');$('#prayer-latin-title').textContent=p.latinTitle;$('#prayer-edition').textContent=(p.date?'Data: '+p.date.split('-').reverse().join('/')+' · ':'')+p.edition+(p.note?' '+p.note:'');$('#prayer-favorite').hidden=p.kind==='Ofício';$('#prayer-favorite').textContent=favorites.includes(p.id)?'★ Favorita':'☆ Favoritar';const source=$('#prayer-source');source.href=safeUrl(p.source)||'#';source.textContent=p.kind==='Ofício'?'Abrir ofício na fonte ↗':p.textOrigin==='editorial'?'Referência da devoção ↗':p.textOrigin==='common'?'Conferir texto do Comum ↗':'Conferir fórmula latina ↗';renderText();configurePlayer();if(tab==='prayers')renderList();$('#prayer-reader').scrollIntoView({block:'start',behavior:'smooth'});}
function renderText(){$('#prayer-text').className='prayer-text view-'+reading;$('#prayer-text').innerHTML=prayer.sections.map((s,i)=>`<section class="prayer-verse" data-verse="${i}" tabindex="-1"><div lang="pt-BR" class="pt"><span class="language-tag">PORTUGUÊS</span><p>${esc(s.pt)}</p></div><div lang="la" class="la"><span class="language-tag">LATINE</span><p>${esc(s.la)}</p></div></section>`).join('');}
function configurePlayer(){if(!player||!prayer)return;const lang=$('#prayer-audio-language').value;const voice=selectVoice(voices,lang,$('#prayer-voice').value);player.configure({sections:prayer.sections,lang,voice,rate:Number($('#prayer-speed').value),gap:Number($('#prayer-gap').value)});}
function renderVoices(){if(!player)return;voices=speechSynthesis.getVoices();const lang=$('#prayer-audio-language').value;const selected=$('#prayer-voice').value;const sorted=[...voices].sort((a,b)=>Number(b.lang.toLowerCase().startsWith(lang))-Number(a.lang.toLowerCase().startsWith(lang))||Number(b.localService)-Number(a.localService));$('#prayer-voice').innerHTML='<option value="">Automática no idioma escolhido</option>'+sorted.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} · ${esc(v.lang)} · ${v.localService?'local':'serviço online'}</option>`).join('');if(voices.some(v=>v.voiceURI===selected))$('#prayer-voice').value=selected;const voice=selectVoice(voices,lang,selected);$('#prayer-voice-note').textContent=lang==='la'&&!voice?'Não foi encontrada voz latina. Você pode escolher uma voz italiana como aproximação; a pronúncia não será garantida.':voice&&!voice.localService?'A voz selecionada usa um serviço online do navegador.':'A pronúncia depende da voz instalada. A leitura é falada, não canto litúrgico.';configurePlayer();}
async function loadHour(hour){if(STATIC_EDITION)return;const generation=++requestGeneration;player?.stop();$$('[data-hour]').forEach(b=>b.disabled=true);status('Carregando o ofício bilíngue…');try{const query=new URLSearchParams({hour,date:$('#office-date').value,version:$('#office-version').value,votive:'Hodie'});const r=await fetch('./api/oratorio/office?'+query,{signal:AbortSignal.timeout(30000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Não foi possível carregar o ofício.');if(generation!==requestGeneration)return;setPrayer(d);status('Carregado para '+d.date.split('-').reverse().join('/')+' · '+d.edition+'. Confira a indicação de idioma nas duas colunas.');}catch(e){if(generation===requestGeneration)status(e.name==='TimeoutError'?'A fonte demorou a responder. Tente novamente.':e.message);}finally{if(generation===requestGeneration)$$('[data-hour]').forEach(b=>b.disabled=false);}}
function renderHours(){
 if(!STATIC_EDITION){$('#office-hours').innerHTML=Object.entries(hours).map(([id,[name,caption]])=>`<button data-hour="${id}" class="hour-card"><strong>${name}</strong><span>${caption}</span><b>↗</b></button>`).join('');return;}
 try{$('#office-hours').innerHTML=Object.entries(hours).map(([id,[name,caption]])=>`<a class="hour-card" href="${esc(publicOfficeUrl($('#office-date').value,id,$('#office-version').value))}" target="_blank" rel="noopener noreferrer" aria-label="Abrir ${name} na fonte original"><strong>${name}</strong><span>${caption} · Abrir na fonte</span><b>↗</b></a>`).join('');status('As horas abrem na fonte original em uma nova aba.');}catch(e){$('#office-hours').innerHTML='';status(e.message);}
}
function chooseTab(value){tab=value;player?.stop();$('#prayer-library').hidden=tab!=='prayers';$('#office-library').hidden=tab!=='office';$$('[data-oratory-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.oratoryTab===tab)));}
async function init(){try{const r=await fetch('./prayers.json');if(!r.ok)throw Error();data=await r.json();}catch{status('Não foi possível abrir o livro de orações. Recarregue o app.');return;}$('#prayer-category').innerHTML='<option value="">Todas as devoções</option>'+[...new Set(data.entries.map(p=>p.category))].map(c=>`<option>${esc(c)}</option>`).join('');$('#prayer-intention').innerHTML='<option value="">Todas as intenções</option>'+[...new Set(data.entries.flatMap(p=>p.intentions||[]))].sort((a,b)=>a.localeCompare(b,'pt-BR')).map(t=>'<option>'+esc(t)+'</option>').join('');$('#prayer-total').textContent=data.entries.length+' textos prontos · Português e latim';const now=new Date();$('#office-date').value=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');renderHours();$('#office-date').addEventListener('change',renderHours);$('#office-version').addEventListener('change',renderHours);
 if('speechSynthesis'in window&&'SpeechSynthesisUtterance'in window){player=new PrayerPlayer({synth:speechSynthesis,Utterance:SpeechSynthesisUtterance,onChange(s){$('#prayer-play').textContent=s.state==='playing'?'Ⅱ Pausar':s.state==='paused'?'▶ Continuar':'▶ Ouvir e acompanhar';$('#prayer-progress').textContent=s.state==='finished'?'Oração concluída.':s.total?'Trecho '+Math.min(s.index+1,s.total)+' de '+s.total:'Escolha uma oração';$('#prayer-audio-progress').max=Math.max(1,s.total);$('#prayer-audio-progress').value=s.state==='finished'?s.total:s.index;$$('.prayer-verse').forEach(e=>e.classList.toggle('speaking',Number(e.dataset.verse)===s.section&&['playing','paused'].includes(s.state)));if(s.state==='playing')$('[data-verse="'+s.section+'"]')?.scrollIntoView({behavior:'smooth',block:'nearest'});},onError:status});speechSynthesis.addEventListener('voiceschanged',renderVoices);renderVoices();}else{$('#prayer-audio-controls').hidden=true;$('#prayer-voice-note').textContent='Este navegador não oferece leitura por voz. Os textos continuam disponíveis. Experimente Edge ou Chrome.';}
 $('#prayer-search').oninput=renderList;$('#prayer-category').onchange=renderList;$('#prayer-intention').onchange=renderList;$('#prayer-favorites').onchange=renderList;$('#prayer-view').onchange=()=>{reading=$('#prayer-view').value;if(prayer)renderText();};$('#prayer-audio-language').onchange=()=>{$('#prayer-voice').value='';renderVoices();};$('#prayer-voice').onchange=renderVoices;$('#prayer-speed').onchange=configurePlayer;$('#prayer-gap').onchange=configurePlayer;
 $('#prayer-play').onclick=()=>{if(!prayer){status('Escolha uma oração primeiro.');return;}if(player.state==='playing')player.pause();else player.play();};$('#prayer-stop').onclick=()=>player?.stop();$('#prayer-prev').onclick=()=>player?.step(-1);$('#prayer-next').onclick=()=>player?.step(1);
 $('#prayer-favorite').onclick=()=>{if(!prayer)return;favorites=favorites.includes(prayer.id)?favorites.filter(x=>x!==prayer.id):[...favorites,prayer.id];try{localStorage.setItem('ci-oratory-favorites',JSON.stringify(favorites));}catch{status('Não foi possível salvar os favoritos neste navegador.');}$('#prayer-favorite').textContent=favorites.includes(prayer.id)?'★ Favorita':'☆ Favoritar';renderList();};
 $('#prayer-copy').onclick=async()=>{if(!prayer)return;try{await navigator.clipboard.writeText(prayer.title+'\n\n'+prayer.sections.map(s=>reading==='pt'?s.pt:reading==='la'?s.la:s.pt+'\n\n'+s.la).join('\n\n')+'\n\nFonte: '+prayer.source);status('Texto copiado com a fonte.');}catch{status('Não foi possível copiar. Selecione o texto e copie manualmente.');}};
 $('#prayer-print').onclick=()=>{if(prayer)window.print();};document.addEventListener('click',e=>{const p=e.target.closest('[data-prayer]'),t=e.target.closest('[data-oratory-tab]'),h=e.target.closest('[data-hour]');if(p)setPrayer(data.entries.find(x=>x.id===p.dataset.prayer));if(t)chooseTab(t.dataset.oratoryTab);if(h)loadHour(h.dataset.hour);});
 window.addEventListener('hashchange',()=>{if(location.hash!=='#oratorio'){player?.stop();requestGeneration++;$$('[data-hour]').forEach(b=>b.disabled=false);}});window.addEventListener('pagehide',()=>player?.stop());document.addEventListener('visibilitychange',()=>{if(document.hidden&&player?.state==='playing'){player.pause();status('Leitura pausada porque a página ficou em segundo plano. Pressione Continuar para retomar.');}});renderList();
}
init();
